-- evt:great_lock
RegisterEvent(31, "Great lock", function()
    if not ((HasItem(12261)) and (IsAtLeast(MapVar(16), 1)) and (IsAtLeast(MapVar(17), 1)) and (IsAtLeast(MapVar(18), 1)) and (not (IsAtLeast(MapVar(19), 1)))) then
        if not HasItem(12261) then
            evt.SimpleMessage('A lock as big as a door is set in the floor, held by three bolts. Its keyhole is cut for a great iron key.')
        else
            local n = 0
            if not IsAtLeast(MapVar(16), 1) then n = n + 1 end
            if not IsAtLeast(MapVar(17), 1) then n = n + 1 end
            if not IsAtLeast(MapVar(18), 1) then n = n + 1 end
            if n == 0 then evt.StatusText('The great lock lies open.', 4) else
            evt.SimpleMessage(tr('The Iron Key will not turn: {count} of the three bolts still hold the lock. Their levers are in this hall and in the rooms north and east.', {count = n})) end
        end
        return
    end
    evt.SetDoorState(20, DoorAction.Open)
    SetValue(MapVar(19), 1)
    evt.SimpleMessage("The Iron Key turns. All is set: the great lock slides aside, and a stair goes down into a cold light.")
end, "Great lock")

